import fs from'node:fs';import assert from'node:assert/strict';import{toolDependency}from './refresh-deps.mjs';import{actionPosePath,thinkingPose,warmPlayPose}from '../games/poker/presentation.mjs';const sharp=toolDependency('sharp'),manifest=JSON.parse(fs.readFileSync('games/poker/art/animation-v2/manifest.json'));assert.equal(manifest.assets.length,30);let requests=0;globalThis.Image=class{set src(value){requests++;this.naturalWidth=480;queueMicrotask(()=>this.onload())}};
for(const role of ['growth','luck','healing','memory','joy','night','trust','dream','sadness','hope']){const base='art/seat-'+role+'.webp';assert.equal(thinkingPose(role),base);await Promise.all([warmPlayPose('art/animation-v2/'+role+'-think.webp'),warmPlayPose('art/animation-v2/'+role+'-think.webp')]);assert.equal(thinkingPose(role),'art/animation-v2/'+role+'-think.webp');for(const source of [base,thinkingPose(role)]){assert.equal(actionPosePath(source,'play'),'art/seat-'+role+'-play-v1.webp');for(const type of ['hit','draw','double'])assert.equal(actionPosePath(source,type),'art/animation-v2/'+role+'-draw.webp');for(const type of ['pass','stand'])assert.equal(actionPosePath(source,type),'art/animation-v2/'+role+'-pass.webp');}for(const pose of ['think','draw','pass']){const m=await sharp('games/poker/art/animation-v2/'+role+'-'+pose+'.webp').metadata();assert(m.hasAlpha);}}
assert.equal(requests,10);assert.equal(actionPosePath('art/card-back.webp','draw'),null);console.log('PASS 30 poker pose images decode, own-turn thinking, correct draw/pass/play identity and deduplicated optional loads');
